import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Home from './components/Home';
import Timetable from './components/Timetable';
import Teachers from './components/Teachers';
import About from './components/About';
import LmsDashboard from './components/LmsDashboard';
import Footer from './components/Footer';

export default function App() {
  const [currentPage, setCurrentPage] = useState('Home');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [inputName, setInputName] = useState('');
  const [inputPassword, setInputPassword] = useState('');

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await fetch('http://localhost:5000/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: inputName, password: inputPassword })
      });
      const data = await response.json();
      if (data.status === 'Success') {
        setStudentName(inputName);
        setIsLoggedIn(true);
        setShowLoginModal(false);
        setCurrentPage('Dashboard');
      } else {
        alert('Invalid Username or Password!');
      }
    } catch (error) {
      alert('Error: Server connection failed!');
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setStudentName('');
    setInputName('');
    setInputPassword('');
    setCurrentPage('Home');
  };

  return (
    <div style={{ margin: 0, padding: 0, fontFamily: 'Arial, sans-serif', backgroundColor: '#f4f6f9', minHeight: '100vh' }}>
      <Navbar 
        onLoginClick={() => setShowLoginModal(true)} 
        isLoggedIn={isLoggedIn} 
        studentName={studentName} 
      />

      {currentPage === 'Home' && <Home />}
      {currentPage === 'Classes' && <Timetable />}
      {currentPage === 'Teachers' && <Teachers />}
      {currentPage === 'About' && <About />}
      {currentPage === 'Dashboard' && <LmsDashboard username={studentName} onLogout={handleLogout} />}

      <Footer />

      {showLoginModal && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 }}>
          <div style={{ backgroundColor: '#fff', padding: '40px', borderRadius: '12px', width: '340px' }}>
            <h3 style={{ textAlign: 'center' }}>Login</h3>
            <form onSubmit={handleLoginSubmit}>
              <input type="text" placeholder="Username" required onChange={(e) => setInputName(e.target.value)} style={{ width: '90%', padding: '10px', marginBottom: '10px' }} />
              <input type="password" placeholder="Password" required onChange={(e) => setInputPassword(e.target.value)} style={{ width: '90%', padding: '10px', marginBottom: '10px' }} />
              <button type="submit" style={{ width: '100%', padding: '10px', backgroundColor: '#0056b3', color: '#fff', border: 'none' }}>Sign In</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
